190	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
191	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
192	        if (claim.getStatus() != ClaimStatus.DRAFT) {
193	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
194	        }
195	        refuseLockedByOther(by, claim);
196	        refuseInClosedPeriod(sheetId, claim.getDueBy());
197	        refuseAfterRetirement(person(sheetId, claim.getPersonId()), on);
198	        if (!claim.getLines().isEmpty() && scaled(amount).compareTo(claim.getAmount()) != 0) {
199	            throw new ResponseStatusException(HttpStatus.CONFLICT,
200	                    "A claim with lines has the sum of its lines as its amount.");
201	        }
202	        String corrected = correctedNumber(sheetId, claim.getPersonId(), amount, corrects, claim.getId());
203	        String reference = refOf(sheetId, ref, claim.getId());
204	        RollupService.Snapshot before = rollup.snapshot(sheetId);
205	        claim.setAmount(scaled(amount));
206	        claim.setCorrects(corrected);
207	        claim.setDate(on);
208	        claim.setRoundsOn(roundsOn(sheetId, corrected, on));
209	        claim.setNote(noteOf(note));
210	        claim.setRef(reference);
211	        claim.setTags(tagsOf(tagged));
212	        claim.setEditedBy(by);
213	        // the save closes the editor, which releases the claim
214	        claim.setLockedBy(null);
215	        Claim saved = claims.saveAndFlush(claim);
216	        keepTags(sheetId, saved.getTags());
217	        audit.recordOnCommit(record("CLAIM_EDITED", by, person(sheetId, saved.getPersonId()), saved));
