311	    /**
312	     * Moves the claim to its next status. A part being settled was judged by the four-eyes rules and the proof rule
313	     * on the claim it was split off, so they are not judged on it again.
314	     */
315	    private Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next, String reason, boolean part,
316	            LocalDate on) {
317	        Claim claim = lockedClaim(sheetId, id);
318	        switch (next) {
319	            case OPEN -> settings.refuseUnlessMay(sheetId, by, "open");
320	            case SETTLED -> settings.refuseUnlessMay(sheetId, by, "settle");
321	            case VOID -> settings.refuseUnlessMay(sheetId, by, "void");
322	            default -> {
323	            }
324	        }
325	        RollupService.Snapshot before = rollup.snapshot(sheetId);
326	        String tail = "";
327	        // settling is the step from OPEN; a pending claim is settled by approving it
328	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
329	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
330	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
331	            throw new ResponseStatusException(HttpStatus.CONFLICT,
332	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
333	        }
334	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
335	            throw new ResponseStatusException(HttpStatus.CONFLICT,
336	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
337	        }
338	        if (next == ClaimStatus.SETTLED && !part) {
339	            refuseFourEyes(by, claim);
340	        }
341	        if (next == ClaimStatus.DRAFT && claim.getCorrects() != null) {
342	            // a restored correction counts against its claim again
343	            refuseOverCorrection(sheetId, claim.getPersonId(), claim.getAmount(), claim.getCorrects(), claim.getId());
344	        }
345	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
346	            refuseVoidOfSettled(by, sheetId, claim);
347	            // the frozen figure leaves every total; the claim keeps its number and shows the figure it had
348	            tail = " reversed=" + text(claim.getSettledDue());
349	        }
350	        if (next == ClaimStatus.VOID) {
351	            String voidReason = voidReasons.refuseUnlessListed(sheetId, reason);
352	            claim.setVoidReason(voidReason);
353	            if (voidReason != null) {
354	                tail += " reason=" + voidReason;
355	            }
356	        }
357	        Person person = person(sheetId, claim.getPersonId());
358	        if (next == ClaimStatus.OPEN) {
359	            refuseFlaggedUnlessSteward(by, sheetId, person);
360	            refuseWithoutNote(sheetId, claim);
361	            refuseOverPeriodCap(sheetId, claim);
362	            if (aboveReviewThreshold(sheetId, person, claim)) {
363	                // it waits for a steward's review, and is numbered once it is reviewed
364	                next = ClaimStatus.REVIEW;
365	            } else {
366	                number(sheetId, claim);
367	            }
368	            claim.setOpenedBy(by);
369	        }
370	        String event = switch (next) {
371	            case OPEN -> "CLAIM_OPENED";
372	            case REVIEW -> "CLAIM_REVIEW";
373	            case SETTLED -> "CLAIM_SETTLED";
374	            case VOID -> "CLAIM_VOIDED";
375	            case DRAFT, PENDING, DELETED -> throw new IllegalStateException();
376	        };
377	        if (next == ClaimStatus.SETTLED) {
378	            // the due is fixed at the due a statement bound it to (late charge and floor included), else at the rate
379	            // the person's grade has in force on the claim's date, with the late charge it has gained by today, and
380	            // at least the floor in force on its date; with none it stays live
381	            BigDecimal fixed = on != null ? dueAsOf(sheetId, id, on)
382	                    : claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
383	                    : liveDue(rateFigure(sheetId, person, claim), claim, person, sheets.load(sheetId), true);
384	            if (!part) {
385	                refuseWithoutProof(sheetId, claim, fixed);
386	            }
387	            if (settings.aboveClerkLimit(sheetId, by, person.gradeOn(sheets.load(sheetId).getToday()), fixed)) {
388	                next = ClaimStatus.PENDING;
389	                event = "CLAIM_PENDING";
390	            } else {
391	                claim.setSettledDue(fixed);
392	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString())
393	                        + (on == null ? "" : " on=" + on);
394	            }
395	        }
396	        claim.setStatus(next);
397	        logStatus(by, sheetId, person, claim);
398	        Claim saved = claims.saveAndFlush(claim);
399	        audit.recordOnCommit(record(event, by, person, saved) + tail);
400	        if (next == ClaimStatus.SETTLED) {
401	            watches.notifyWatchers(by, sheetId, person, saved.getNumber());
402	        }
403	        rollup.recordChanges(by, sheetId, before);
404	        return saved;
405	    }
