408	     * The due the claim showed at the end of the day, as the sheet as of that day works it out. Refused for a day after
409	     * the sheet's today, and for a claim the sheet did not hold then.
410	     */
411	    private BigDecimal dueAsOf(String sheetId, Long id, LocalDate on) {
412	        LocalDate today = sheets.load(sheetId).getToday();
413	        if (today != null && on.isAfter(today)) {
414	            throw new ResponseStatusException(HttpStatus.CONFLICT,
415	                    "A claim cannot be settled as of " + on + ", after the sheet's today " + today + ".");
416	        }
417	        record Then(boolean held, BigDecimal due) {
418	        }
419	        Then then = asOf.readAsOf(sheetId, on, () -> claims.findByIdAndSheetId(id, sheetId)
420	                .flatMap(c -> people.findByIdAndSheetId(c.getPersonId(), sheetId)
421	                        .map(p -> new Then(true, due(sheetId, p, c))))
422	                .orElse(new Then(false, null)));
423	        if (!then.held()) {
