502	    /**
503	     * Writes a reminder for an OPEN or PENDING claim, which shows the sheet's today as its reminded date. Refused for
504	     * a claim in any other status and one already reminded on the sheet's today; a reminder changes none of the
505	     * claim's figures, so one whose due-by falls in a closed period may still be reminded. When the sheet has an
506	     * escalation gap and the claim's previous reminder was at least that many days before the sheet's today, the
507	     * claim is escalated: an ESCALATE line follows the REMIND line, once per claim ever.
508	     */
509	    @Transactional
510	    public Claim remind(String by, String sheetId, Long id) {
511	        sheets.lock(sheetId);
512	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
513	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
514	        if (!claim.getStatus().isOpen()) {
515	            throw new ResponseStatusException(HttpStatus.CONFLICT,
516	                    "A " + claim.getStatus() + " claim cannot be reminded.");
517	        }
518	        Sheet sheet = sheets.load(sheetId);
519	        LocalDate today = sheet.getToday();
520	        if (today != null && today.equals(claim.getRemindedOn())) {
521	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today.");
522	        }
523	        Integer gap = sheet.getEscalateAfter();
524	        LocalDate previous = claim.getRemindedOn();
525	        boolean escalate = gap != null && !claim.isEscalated() && previous != null && today != null
526	                && !previous.plusDays(gap).isAfter(today);
527	        claim.setRemindedOn(today);
528	        if (escalate) {
529	            claim.setEscalated(true);
530	        }
531	        Claim saved = claims.saveAndFlush(claim);
532	        Person person = person(sheetId, saved.getPersonId());
533	        audit.recordOnCommit(record("REMIND", by, person, saved));
534	        if (escalate) {
535	            audit.recordOnCommit(record("ESCALATE", by, person, saved));
536	        }
537	        return saved;
538	    }
