608	     * two decimals, a claim that is not a DRAFT, one another user's editor holds, and in a closed period.
609	     */
610	    @Transactional
611	    public Claim addLine(String by, String sheetId, Long id, String label, Integer qty, BigDecimal unit) {
612	        String stripped = label == null ? "" : label.strip();
613	        if (stripped.isEmpty()) {
614	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A line needs a label.");
615	        }
