617	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
618	                    "A line's quantity is a whole number of at least 1.");
619	        }
620	        if (unit == null || unit.signum() < 0 || unit.stripTrailingZeros().scale() > 2) {
621	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
622	                    "A line's unit amount is 0.00 or more, with up to two decimals.");
