    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("COMMENT_ADDED", by, person(sheetId, saved.getPersonId()), saved) + " text="
            + stripped);
    return saved;
}

/**
 * Adds a line to a DRAFT claim: its amount becomes the sum of its lines' quantities times unit amounts. Adding a
 * line edits the claim. Refused for a blank label, a quantity below 1, a unit amount below 0.00 or with more than
 * two decimals, a claim that is not a DRAFT, one another user's editor holds, and in a closed period.
 */
@Transactional
public Claim addLine(String by, String sheetId, Long id, String label, Integer qty, BigDecimal unit) {
    String stripped = label == null ? "" : label.strip();
    if (stripped.isEmpty()) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A line needs a label.");
    }
    if (qty == null || qty < 1) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                "A line's quantity is a whole number of at least 1.");
    }
    if (unit == null || unit.signum() < 0 || unit.stripTrailingZeros().scale() > 2) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                "A line's unit amount is 0.00 or more, with up to two decimals.");
    }
    Claim claim = lockedClaim(sheetId, id);
    if (claim.getStatus() != ClaimStatus.DRAFT) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can take a line.");
    }
    refuseLockedByOther(by, claim);
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    BigDecimal scaledUnit = unit.setScale(2, RoundingMode.UNNECESSARY);
    claim.addLine(stripped, qty, scaledUnit);
    claim.setEditedBy(by);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_LINE_ADDED", by, person(sheetId, saved.getPersonId()), saved) + " label="
            + stripped + " qty=" + qty + " unit=" + scaledUnit.toPlainString());
    rollup.recordChanges(by, sheetId, before);
    return saved;
}

/**
 * Raises the claim's proofs count by one, of the kind (receipt or photo; null for none chosen, a receipt). Refused
 * for any other kind, for a SETTLED, VOID or DELETED claim, and in a closed period.
 */
@Transactional
public Claim addProof(String by, String sheetId, Long id, String kind) {
    if (kind != null && !Claim.PROOF_KINDS.contains(kind)) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "A proof is a receipt or a photo.");
    }
    Claim claim = lockedClaim(sheetId, id);
    if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
            || claim.getStatus() == ClaimStatus.DELETED) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot take a proof.");
    }
    claim.addProof(kind == null ? Claim.PROOF_RECEIPT : kind);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_PROOF_ADDED", by, person(sheetId, saved.getPersonId()), saved)
            + " proofs=" + saved.getProofs() + (kind == null ? "" : " kind=" + kind));
    return saved;
}

/**
 * Refuses settling or approving the claim at the due (null for n/a) when the due is above the proof threshold in
 * force on the claim's date (its person's grade's then when one is set, else the sheet's) and the claim has no
 * proof, or while the sheet's proof kinds are set, lacks a proof of any of them; an n/a due is within any
 * threshold.
 */
private void refuseWithoutProof(String sheetId, Claim claim, BigDecimal due) {
    String grade = person(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
    Sheet sheet = sheets.load(sheetId);
    BigDecimal threshold = sheet.proofThresholdFor(grade, claim.getDate());
    if (threshold == null || due == null || due.compareTo(threshold) <= 0) {
        return;
    }
    if (claim.getProofs() == 0) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A claim with a due above " + threshold.toPlainString() + " needs a proof first.");
    }
    for (String kind : sheet.proofKindList()) {
        if (claim.proofsOf(kind) == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim with a due above " + threshold.toPlainString() + " needs a " + kind + " proof first.");
        }
    }
}

/**
 * Refuses opening the claim when its note is empty and its due is above the note threshold in force on its date;
 * an n/a due is within any threshold.
 */
/**
 * Refuses opening a claim whose due-by falls in a period with a cap when its person already has that many OPEN or
 * PENDING claims due by a date in it. The sheet stays locked until the transaction ends, so two opens are counted
 * in turn.
 */
private void refuseOverPeriodCap(String sheetId, Claim claim) {
    Period period = periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
            claim.getDueBy(), claim.getDueBy()).orElse(null);
    if (period == null || period.getCap() == null) {
        return;
    }
    long held = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
            .filter(c -> !c.getId().equals(claim.getId()))
            .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
            .filter(c -> period.contains(c.getDueBy()))
            .count();
    if (held >= period.getCap()) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has " + period.getCap()
                + " open claims in period " + period.getName() + ".");
    }
}

private void refuseWithoutNote(String sheetId, Claim claim) {
    BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
    if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
        return;
    }
    BigDecimal due = due(sheetId, person(sheetId, claim.getPersonId()), claim);
    if (due != null && due.compareTo(threshold) > 0) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A claim with a due above " + threshold.toPlainString() + " needs a note first.");
    }
}

/**
 * Whether the claim's due is above the review threshold in force on its date, so opening it sends it to REVIEW;
 * an n/a due is within any threshold.
 */
private boolean aboveReviewThreshold(String sheetId, Person person, Claim claim) {
    BigDecimal threshold = sheets.load(sheetId).reviewThresholdOn(claim.getDate());
    if (threshold == null) {
        return false;
    }
    BigDecimal due = due(sheetId, person, claim);
    return due != null && due.compareTo(threshold) > 0;
}

