1150	    @Transactional(readOnly = true)
1151	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
1152	        Sheet sheet = sheets.load(sheetId);
1153	        int count = 0;
1154	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
1155	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1156	            if (!claim.getStatus().isOpen() || claim.getSettledDue() != null || claim.isBound()) {
1157	                continue;
1158	            }
1159	            Person person = person(sheetId, claim.getPersonId());
1160	            if (!grade.equals(person.gradeOn(claim.getDate()))) {
1161	                continue;
