1163	            BigDecimal current = due(sheetId, person, claim);
1164	            BigDecimal figure = dueOn(claim.getAmount(), pct, sheet.roundingOn(claim.getRoundsOn()));
1165	            BigDecimal next = liveDue(figure, claim, person, sheet, true);
1166	            BigDecimal before = current == null ? BigDecimal.ZERO : current;
1167	            if (current == null || before.compareTo(next) != 0) {
1168	                count++;
1169	                diff = diff.add(next.subtract(before));
