1212	     * late-from: its due-by plus its grace) by the sheet's today: for each such boundary (its late-from plus 30, 60,
1213	     * 90 ... days), the sheet's late
1214	     * percent in force on that boundary date of the figure plus the charges of the boundaries before it (it
1215	     * compounds), rounded like its due; a boundary whose percent is 0.00 adds nothing. A deferred claim is not overdue; a waived one bears no charge. While a statement binds the
1216	     * claim, its due as shown then (this charge included) stands instead.
1217	     */
1218	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Person person, Sheet sheet) {
1219	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())
1220	                || claim.isWaivedOn(sheet.getToday())) {
1221	            return figure;
1222	        }
1223	        LocalDate lateFrom = lateFrom(claim, person, sheet);
1224	        long overdue = ChronoUnit.DAYS.between(lateFrom, sheet.getToday());
1225	        long periods = overdue > 0 ? overdue / 30 : 0;
1226	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
1227	        BigDecimal due = figure;
1228	        for (long k = 1; k <= periods; k++) {
1229	            BigDecimal latePct = sheet.latePctOn(lateFrom.plusDays(30 * k));
1230	            if (latePct.signum() != 0) {
1231	                due = due.add(dueOn(due, latePct, rounding));
1232	            }
1233	        }
1234	        return due;
1235	    }
